package nginx

import (
	"context"
	"errors"
	"fmt"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"docklift/internal/certs"
)

var (
	dashboardSetLine  = regexp.MustCompile(`set\s+\$dashboard\s+docklift-(?:nginx|backend)(?:\.docklift_network)?\s*;`)
	dashboardPassLine = regexp.MustCompile(`proxy_pass\s+http://\$dashboard:\d+\s*;`)
)

// rewritePanelUpstream points a dashboard panel conf at
// PanelUpstreamHost:backendPort. Confs proxying elsewhere (host.docker.internal
// ports) are returned unchanged. A conf generated by Docklift 2.x
// becomes byte-identical to what BuildPanelConf generates now.
func rewritePanelUpstream(content string, backendPort int) string {
	if !dashboardSetLine.MatchString(content) {
		return content
	}
	out := dashboardSetLine.ReplaceAllLiteralString(content, "set $dashboard "+PanelUpstreamHost+";")
	return dashboardPassLine.ReplaceAllLiteralString(out, "proxy_pass http://$dashboard:"+strconv.Itoa(backendPort)+";")
}

// MigratePanelUpstreams is the one-time boot migration of the Go layout:
// panel confs written for the removed docklift-nginx gateway
// (`set $dashboard docklift-nginx; proxy_pass http://$dashboard:80;`) are
// rewritten to PanelUpstreamHost:<PORT> (the unqualified docklift-backend an
// earlier Go build wrote is qualified too), then nginx is reloaded. It is
// idempotent (an up-to-date conf is left alone, so a second run changes
// nothing and does not reload) and also follows a changed PORT.
//
// Each file is replaced atomically. If nginx rejects the rewritten
// configuration, every original is restored and the error returned; if nginx
// cannot be run, the rewritten files stay (they are the correct ones for the
// new layout — nginx-proxy loads them when it next starts) and the reload
// error is returned. It returns the names of the rewritten files.
func (s *Service) MigratePanelUpstreams(ctx context.Context) ([]string, error) {
	files, err := s.panelFiles()
	if err != nil {
		return nil, err
	}
	type change struct{ name, old string }
	var changed []change
	restore := func() error {
		var errs []error
		for _, c := range changed {
			if err := certs.WriteFileAtomic(filepath.Join(s.confDir, c.name), []byte(c.old), 0o644); err != nil {
				errs = append(errs, err)
			}
		}
		return errors.Join(errs...)
	}
	for _, f := range files {
		next := rewritePanelUpstream(f.content, s.backendPort)
		if next == f.content {
			continue
		}
		if err := certs.WriteFileAtomic(filepath.Join(s.confDir, f.name), []byte(next), 0o644); err != nil {
			return nil, errors.Join(fmt.Errorf("rewrite %s: %w", f.name, err), restore())
		}
		changed = append(changed, change{f.name, f.content})
	}
	if len(changed) == 0 {
		return nil, nil
	}
	names := make([]string, len(changed))
	for i, c := range changed {
		names[i] = c.name
	}
	if verdict, detail := s.reloader.Test(ctx); verdict == testInvalid {
		if err := restore(); err != nil {
			return nil, errors.Join(&ReloadError{Detail: detail}, err)
		}
		return nil, &ReloadError{Detail: detail, RolledBack: true}
	}
	s.log.Info("Panel domains now proxy to " + PanelUpstreamHost + ": " + strings.Join(names, ", "))
	if err := s.Reload(ctx); err != nil {
		return names, err
	}
	return names, nil
}
